SELECT id, region, opened_date, sqft, SUM(sqft) OVER (PARTITION BY region ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, FIRST_VALUE(region, TRUE) OVER (PARTITION BY region, city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date, id) AS row_seq FROM stores WHERE city != 'Singapore';
